package by.bsuir.catalog;
import by.bsuir.repair.contract.*; import by.bsuir.repair.runtime.*; import io.grpc.Status; import io.grpc.stub.StreamObserver; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class CatalogGrpcService extends CatalogServiceGrpc.CatalogServiceImplBase {
 private final JdbcTemplate jdbc; private final StringRedisTemplate redis; private final Jsons jsons; private final OutboxService outbox;
 public CatalogGrpcService(JdbcTemplate jdbc,StringRedisTemplate redis,Jsons jsons,OutboxService outbox){this.jdbc=jdbc;this.redis=redis;this.jsons=jsons;this.outbox=outbox;}
 @Override public void listServices(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);boolean active=jsons.bool(in,"activeOnly",true);jsons.reply(obs,cached("catalog:services:"+active,"select id,name,base_price price,active from services"+(active?" where active=true":"")+" order by name"));}catch(Throwable e){jsons.fail(obs,e);}}
 @Override public void listParts(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);boolean stock=jsons.bool(in,"inStockOnly",true);jsons.reply(obs,cached("catalog:parts:"+stock,"select id,sku,name,unit_price AS price,stock_qty AS \"stockQuantity\",active from spare_parts where active=true"+(stock?" and stock_qty>0":"")+" order by name"));}catch(Throwable e){jsons.fail(obs,e);}}
 private List<Map<String,Object>> cached(String key,String sql){try{String value=redis.opsForValue().get(key);if(value!=null){Object parsed=jsons.read("{\"value\":"+value+"}").get("value");@SuppressWarnings("unchecked")var list=(List<Map<String,Object>>)parsed;return list;}}catch(Exception ignored){}var rows=jdbc.queryForList(sql);try{redis.opsForValue().set(key,jsons.writeString(rows),Duration.ofMinutes(5));}catch(Exception ignored){}return rows;}
 @Override @Transactional public void upsertService(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);requireAdmin(in);String idText=jsons.optional(in,"id");UUID id=idText==null?UUID.randomUUID():UUID.fromString(idText);if(count("services",id)==0)jdbc.update("insert into services(id,name,base_price,active,updated_at) values(?,?,?,?,?)",id,jsons.string(in,"name"),decimal(in,"price"),jsons.bool(in,"active",true),java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC));else jdbc.update("update services set name=?,base_price=?,active=?,updated_at=? where id=?",jsons.string(in,"name"),decimal(in,"price"),jsons.bool(in,"active",true),java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC),id);invalidate();var value=jdbc.queryForMap("select id,name,base_price price,active from services where id=?",id);outbox.enqueue(EventTopics.CATALOG,"ServiceUpdated",id,value);jsons.reply(obs,value);}catch(Throwable e){jsons.fail(obs,e);}}
 @Override @Transactional public void upsertPart(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);requireAdmin(in);String idText=jsons.optional(in,"id");UUID id=idText==null?UUID.randomUUID():UUID.fromString(idText);if(count("spare_parts",id)==0)jdbc.update("insert into spare_parts(id,sku,name,unit_price,stock_qty,active,updated_at) values(?,?,?,?,?,?,?)",id,jsons.string(in,"sku"),jsons.string(in,"name"),decimal(in,"price"),jsons.integer(in,"stockQuantity",0),jsons.bool(in,"active",true),java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC));else jdbc.update("update spare_parts set sku=?,name=?,unit_price=?,stock_qty=?,active=?,updated_at=? where id=?",jsons.string(in,"sku"),jsons.string(in,"name"),decimal(in,"price"),jsons.integer(in,"stockQuantity",0),jsons.bool(in,"active",true),java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC),id);invalidate();var value=part(id);outbox.enqueue(EventTopics.CATALOG,"SparePartUpdated",id,value);jsons.reply(obs,value);}catch(Throwable e){jsons.fail(obs,e);}}
 @Override public void checkParts(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);@SuppressWarnings("unchecked")var items=(List<Map<String,Object>>)in.getOrDefault("items",List.of());List<String> unavailable=new ArrayList<>();for(var item:items){UUID id=UUID.fromString(item.get("partId").toString());int qty=Integer.parseInt(item.get("quantity").toString());var p=part(id);if(Integer.parseInt(p.get("stockQuantity").toString())<qty)unavailable.add(id.toString());}jsons.reply(obs,Map.of("available",unavailable.isEmpty(),"unavailablePartIds",unavailable));}catch(Throwable e){jsons.fail(obs,e);}}
 @Override @Transactional public void reserveParts(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);String key=jsons.string(in,"idempotencyKey");var old=jdbc.queryForList("select response_payload from part_reservations where idempotency_key=?",key);if(!old.isEmpty()){obs.onNext(JsonMessage.newBuilder().setJson(old.get(0).get("response_payload").toString()).build());obs.onCompleted();return;}@SuppressWarnings("unchecked")var items=(List<Map<String,Object>>)in.getOrDefault("items",List.of());List<Map<String,Object>> reserved=new ArrayList<>();for(var item:items){UUID id=UUID.fromString(item.get("partId").toString());int qty=Integer.parseInt(item.get("quantity").toString());var p=part(id);if(jdbc.update("update spare_parts set stock_qty=stock_qty-?,updated_at=? where id=? and active=true and stock_qty>=?",qty,java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC),id,qty)==0)throw Status.FAILED_PRECONDITION.withDescription("Insufficient stock for part "+id).asRuntimeException();reserved.add(Map.of("partId",id,"name",p.get("name"),"price",p.get("price"),"quantity",qty));}var response=Map.of("reserved",true,"items",reserved);jdbc.update("insert into part_reservations(id,idempotency_key,work_order_id,response_payload,created_at) values(?,?,?,?,?)",UUID.randomUUID(),key,UUID.fromString(jsons.string(in,"workOrderId")),jsons.writeString(response),java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC));invalidate();jsons.reply(obs,response);}catch(Throwable e){jsons.fail(obs,e);}}
 private int count(String table,UUID id){return jdbc.queryForObject("select count(*) from "+table+" where id=?",Integer.class,id);}private java.math.BigDecimal decimal(Map<String,Object>m,String k){return new java.math.BigDecimal(jsons.string(m,k));}private void requireAdmin(Map<String,Object>m){if(!"ADMIN".equals(jsons.string(m,"role")))throw new SecurityException("Administrator role is required");}
 private Map<String,Object> part(UUID id){var rows=jdbc.queryForList("select id,sku,name,unit_price AS price,stock_qty AS \"stockQuantity\",active from spare_parts where id=? and active=true",id);if(rows.isEmpty())throw Status.NOT_FOUND.withDescription("Spare part not found").asRuntimeException();return rows.get(0);}private void invalidate(){try{var keys=redis.keys("catalog:*");if(keys!=null&&!keys.isEmpty())redis.delete(keys);}catch(Exception ignored){}}
}


